VIEW `patient_monthly_assesment_with_total_score` AS (select `patient_monthly_assesment`.`patient_id`, `patient_monthly_assesment`.`monthly_assesment_id`, `patient_monthly_assesment`.`weight`, `patient_monthly_assesment`.`height`, `monthly_assesment`.`month`, sum(`patient_daily_assesment`.`score`) as `totalScore` from `patient_monthly_assesment` inner join `monthly_assesment` on `patient_monthly_assesment`.`monthly_assesment_id` = `monthly_assesment`.`id` left join `patient_daily_assesment` on `patient_monthly_assesment`.`patient_id` = `patient_daily_assesment`.`patient_id` left join `daily_assesment` on `patient_daily_assesment`.`daily_assesment_id` = `daily_assesment`.`id` where `patient_monthly_assesment`.`monthly_assesment_id` = `daily_assesment`.`monthly_assesment_id` group by `patient_monthly_assesment`.`patient_id`, `patient_monthly_assesment`.`monthly_assesment_id`, `patient_monthly_assesment`.`weight`, `patient_monthly_assesment`.`height`, `monthly_assesment`.`month`);